/* Career assistant: language detection (English / Hindi / Hinglish), rule-based answers from the analysis, optional server AI. */
(function(root){
const STRONG=/\b(kya|hai|hain|nahi|nahin|mujhe|batao|bataiye|samjhao|samjhaiye|mera|meri|mere|kaise|chahiye|kyun|kyu|karun|karu|aapka|accha|achha|kitna|kaun|kab|sakta|sakti|hoga|wala|wali)\b/gi;
function detect(t){const dev=(t.match(/[\u0900-\u097F]/g)||[]).length,let_=(t.match(/\p{L}/gu)||[]).length||1;
 if(dev/let_>0.3)return"hi";const h=new Set((t.toLowerCase().match(STRONG)||[]));return h.size>=1&&(h.size>=2||t.split(/\s+/).length<=6)?"hing":"en"}
const ctxOf=R=>R&&{score:R.score,req:R.req,matched:R.matched,missing:R.missing,weak:R.weak.map(w=>({phrase:w.phrase,n:w.n})),issues:R.st.filter(x=>x.sev=="high"||x.sev=="medium").map(x=>x.title),bullets:R.bl.length};
const L=(en,hi,hing)=>({en,hi,hing}),j=a=>a.join(", ");
function intent(q){const s=q.toLowerCase();
 if(/score|ats|match|percent|%|स्कोर|अंक/.test(s))return"score";
 if(/missing|gap|keyword|kami|skills?\b|कमी|स्किल|कीवर्ड/.test(s))return"missing";
 if(/verb|weak|vague|action|कमजोर|कमज़ोर/.test(s))return"weak";
 if(/bullet|project|improve|rewrite|likh|सुधार|प्रोजेक्ट/.test(s))return"bullet";
 if(/structure|format|section|heading|फॉर्मेट|फ़ॉर्मेट|सेक्शन/.test(s))return"structure";
 if(/job description|\bjd\b|role|internship|जॉब|इंटर्न/.test(s))return"jd";
 if(/next|suggest|career|advice|what should|karu|karun|सुझाव|सलाह|आगे/.test(s))return"next";
 return"help"}
function rules(q,c){const l=detect(q);if(!c)return{lang:l,text:L("Run an analysis first (paste your resume and a job description), then I can explain your results. I can reply in English, Hindi or Hinglish.","पहले विश्लेषण चलाएँ (अपना रिज़्यूमे और जॉब डिस्क्रिप्शन डालें), फिर मैं आपके नतीजे समझा सकता हूँ। मैं अंग्रेज़ी, हिंदी और हिंग्लिश में जवाब दे सकता हूँ।","Pehle analysis chalayein (resume aur job description daalein), phir main aapke results samjha sakta hoon. Main English, Hindi aur Hinglish mein jawab de sakta hoon.")[l]};
 const m=c.matched.length,r=c.req.length,miss=j(c.missing),weak=j(c.weak.map(w=>w.phrase)),iss=j(c.issues),k=intent(q);
 const A={
 score:L(`Your score is ${c.score}%: ${m} of the ${r} skills named in the job description also appear in your resume. It only measures keyword overlap. It does not predict whether an ATS will select or reject you.`,`आपका स्कोर ${c.score}% है: जॉब डिस्क्रिप्शन की ${r} स्किल्स में से ${m} आपके रिज़्यूमे में मिलीं। यह सिर्फ़ कीवर्ड मैच दिखाता है, ATS में चयन या अस्वीकृति की भविष्यवाणी नहीं करता।`,`Aapka score ${c.score}% hai: job description ki ${r} skills mein se ${m} aapke resume mein mili. Yeh sirf keyword overlap batata hai, ATS selection ya rejection predict nahi karta.`),
 missing:c.missing.length?L(`Skills in the job description but not found in your resume: ${miss}. Add one only if you genuinely have it, for example in a project you actually built. Do not list skills you have not used.`,`ये स्किल्स जॉब डिस्क्रिप्शन में हैं पर आपके रिज़्यूमे में नहीं मिलीं: ${miss}। इन्हें तभी जोड़ें जब आपके पास सच में अनुभव हो, जैसे किसी असली प्रोजेक्ट में। जो स्किल आपने इस्तेमाल नहीं की, वह न लिखें।`,`Yeh skills job description mein hain par aapke resume mein nahi mili: ${miss}. Inhe tabhi add karein jab aapke paas sach mein experience ho, jaise kisi asli project mein. Jo skill use nahi ki, woh na likhein.`):L("None of the skills I recognize in the job description are missing from your resume.","जॉब डिस्क्रिप्शन की जो स्किल्स मैं पहचानता हूँ, उनमें से कोई आपके रिज़्यूमे में गायब नहीं है।","Job description ki jo skills main pehchanta hoon, unmein se koi aapke resume mein missing nahi hai."),
 weak:c.weak.length?L(`Weak or vague phrases found: ${weak}. Replace them with specific verbs like Developed, Implemented or Designed, but only where that describes what you really did.`,`कमज़ोर या अस्पष्ट शब्द मिले: ${weak}। इन्हें Developed, Implemented या Designed जैसे स्पष्ट क्रियाओं से बदलें, पर तभी जब वह आपके असली काम को दर्शाए।`,`Weak ya vague phrases mile: ${weak}. Inhe Developed, Implemented ya Designed jaise specific verbs se badlein, par sirf tab jab woh aapke asli kaam ko describe kare.`):L("No weak phrases were detected.","कोई कमज़ोर शब्द नहीं मिला।","Koi weak phrase nahi mila."),
 bullet:L(`A strong bullet is: action verb + what you built + technologies + purpose. The Results page shows ${c.bullets} suggested rewrite(s) that only change the opening verb. Add extra details yourself only if they are true, and never add numbers you cannot verify.`,`अच्छा बुलेट ऐसा होता है: एक्शन वर्ब + क्या बनाया + कौन सी टेक्नोलॉजी + मकसद। रिज़ल्ट पेज पर ${c.bullets} सुझाए गए बदलाव हैं जो सिर्फ़ शुरुआती क्रिया बदलते हैं। अतिरिक्त जानकारी तभी जोड़ें जब वह सच हो, और ऐसे नंबर कभी न जोड़ें जिन्हें आप साबित न कर सकें।`,`Achha bullet aisa hota hai: action verb + kya banaya + technologies + purpose. Results page par ${c.bullets} suggested rewrite hain jo sirf opening verb badalte hain. Extra details sirf tab add karein jab woh sach ho, aur aise numbers kabhi na daalein jo aap prove nahi kar sakte.`),
 structure:c.issues.length?L(`Main structure issues: ${iss}. See the Structure section for the fix for each one.`,`मुख्य स्ट्रक्चर समस्याएँ: ${iss}। हर एक का समाधान स्ट्रक्चर सेक्शन में दिया है।`,`Main structure issues: ${iss}. Har ek ka fix Structure section mein diya hai.`):L("No high or medium structure issues were found. I can only check text, not fonts or layout.","कोई गंभीर स्ट्रक्चर समस्या नहीं मिली। मैं सिर्फ़ टेक्स्ट जाँच सकता हूँ, फ़ॉन्ट या लेआउट नहीं।","Koi high ya medium structure issue nahi mila. Main sirf text check kar sakta hoon, font ya layout nahi."),
 jd:L(`The job description names ${r} skills I recognize: ${j(c.req)}. Skills outside my fixed list are not counted, so read the posting yourself too.`,`जॉब डिस्क्रिप्शन में ${r} स्किल्स हैं जिन्हें मैं पहचानता हूँ: ${j(c.req)}। मेरी तय सूची से बाहर की स्किल्स गिनी नहीं जातीं, इसलिए पोस्टिंग खुद भी पढ़ें।`,`Job description mein ${r} skills hain jinhe main pehchanta hoon: ${j(c.req)}. Meri fixed list ke bahar ki skills count nahi hoti, isliye posting khud bhi padhein.`),
 next:L(`Suggested next steps: ${c.missing.length?`1) For ${miss}, add them only if you have real experience, or build a small project to learn them. `:""}${c.weak.length?"2) Replace weak phrases with specific verbs. ":""}3) Make each project bullet say what you built, with which technologies, and why.`,`अगले कदम: ${c.missing.length?`1) ${miss} तभी जोड़ें जब असली अनुभव हो, या सीखने के लिए छोटा प्रोजेक्ट बनाएँ। `:""}${c.weak.length?"2) कमज़ोर शब्दों को स्पष्ट क्रियाओं से बदलें। ":""}3) हर प्रोजेक्ट बुलेट में बताएँ कि क्या बनाया, किस टेक्नोलॉजी से, और क्यों।`,`Next steps: ${c.missing.length?`1) ${miss} tabhi add karein jab real experience ho, ya seekhne ke liye chhota project banayein. `:""}${c.weak.length?"2) Weak phrases ko specific verbs se badlein. ":""}3) Har project bullet mein batayein ki kya banaya, kin technologies se, aur kyun.`),
 help:L("I can explain your ATS score, missing skills, weak verbs, project bullets, resume structure and the job description. Ask me in English, Hindi or Hinglish.","मैं आपका ATS स्कोर, मिसिंग स्किल्स, कमज़ोर शब्द, प्रोजेक्ट बुलेट, रिज़्यूमे स्ट्रक्चर और जॉब डिस्क्रिप्शन समझा सकता हूँ। हिंदी, अंग्रेज़ी या हिंग्लिश में पूछें।","Main aapka ATS score, missing skills, weak verbs, project bullets, resume structure aur job description samjha sakta hoon. English, Hindi ya Hinglish mein poochein.")};
 return{lang:l,text:A[k][l]}}
let aiOk=null;
async function ask(history,q,R){const c=ctxOf(R);
 if(aiOk===null)try{aiOk=!!(await(await fetch("/api/health")).json()).ai}catch(e){aiOk=false}
 if(aiOk){try{const res=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({messages:[...history,{role:"user",content:q}],context:c&&{...c,resume:R.resume.slice(0,5000)}})});
  if(res.ok){const d=await res.json();if(d.text)return{text:d.text,via:"ai",lang:detect(q)}}}catch(e){}}
 return{...rules(q,c),via:"rules"}}
const api={detect,rules,ask,ctxOf};root.CVAssistant=api;if(typeof module!=="undefined")module.exports=api;
})(typeof window!=="undefined"?window:globalThis);
